from solution import find_Max_Num


def test_issue_example():
    """Check largest number from [1,2,3] is 321."""
    assert find_Max_Num([1, 2, 3], 3) == 321  # 3*100 + 2*10 + 1 = 321


def test_issue_already_descending():
    """Check largest number from [3,2,1] is still 321."""
    assert find_Max_Num([3, 2, 1], 3) == 321  # 3*100 + 2*10 + 1 = 321


def test_issue_four_digits():
    """Check largest number from [1,4,2,3] is 4321."""
    assert find_Max_Num([1, 4, 2, 3], 4) == 4321  # 4*1000 + 3*100 + 2*10 + 1 = 4321


def test_issue_includes_zero():
    """Check largest number from [1,0,2] is 210."""
    assert find_Max_Num([1, 0, 2], 3) == 210  # 2*100 + 1*10 + 0 = 210


def test_issue_all_zeros():
    """Check largest number from [0,0,0] is 0."""
    assert find_Max_Num([0, 0, 0], 3) == 0  # 0*100 + 0*10 + 0 = 0


def test_issue_duplicate_digits():
    """Check largest number from [2,1,2] is 221."""
    assert find_Max_Num([2, 1, 2], 3) == 221  # 2*100 + 2*10 + 1 = 221


def test_issue_single_digit():
    """Check largest number from [7] is 7."""
    assert find_Max_Num([7], 1) == 7  # 7 = 7


def test_issue_single_zero():
    """Check largest number from [0] is 0."""
    assert find_Max_Num([0], 1) == 0  # 0 = 0


def test_issue_large_mixed_set():
    """Check largest number from [4,9,1,3,8] is 98431."""
    assert find_Max_Num([4, 9, 1, 3, 8], 5) == 98431  # 9*10000 + 8*1000 + 4*100 + 3*10 + 1 = 98431


def test_issue_all_same_nonzero():
    """Check largest number from [5,5,5] is 555."""
    assert find_Max_Num([5, 5, 5], 3) == 555  # 5*100 + 5*10 + 5 = 555


def test_contract_result_is_int():
    """Contract: example result 321 must be an int."""
    assert isinstance(find_Max_Num([1, 2, 3], 3), int)


def test_contract_takes_two_arguments():
    """Contract: public interface is find_Max_Num(arr, n) taking two arguments."""
    assert find_Max_Num.__code__.co_argcount == 2  # expects 2 params: arr and n
